  protected readonly sheetDueTotal = computed(() => {
    let total = 0;
    for (const p of this.people()) total += this.dueCentsOf(p) ?? 0;
    return money(total);
  });
  protected readonly editingId = signal<number | null>(null);
  /** The version of the person the editor loaded. */
