1	import { test, expect } from '@playwright/test';
2	import * as ui from '../support/ui';
3	
4	test.setTimeout(240_000);
5	test.describe("statements", () => {
6	  test("statements", { tag: '@functionality' }, async ({ browser }) => {
7	    const sheet = ui.sheetId();
8	    const pg_uma = await ui.userPage(browser, "uma", sheet);
9	    await ui.setToday(pg_uma, "2026-03-10");
10	    expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "10.00"})).toBe(true);
11	    expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "12.50"})).toBe(true);
12	    const p_ada = ui.must(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "A"}));
13	    const p_ben = ui.must(await ui.addPerson(pg_uma, {"name": "Ben", "grade": "B"}));
14	    const c_ada_0 = ui.must(await ui.addClaim(pg_uma, p_ada, {"amount": "10.25", "date": "2026-03-01"}));
15	    const c_ada_1 = ui.must(await ui.addClaim(pg_uma, p_ada, {"amount": "20.00"}));
16	    const c_ben_0 = ui.must(await ui.addClaim(pg_uma, p_ben, {"amount": "4.00"}));
17	    expect(await ui.claimAction(pg_uma, c_ada_0, "open")).toBe(true);
